evidence={'trial':'ALINA adjuvant; ALEX first-line advanced; Ou phase II post-crizotinib','population':'Distinct resected, untreated advanced and crizotinib-refractory ALK-positive NSCLC groups.','comparison':'Alectinib versus platinum chemotherapy in ALINA; versus crizotinib in ALEX; no comparator in the Ou phase II study.','applicability':evidence_text,'endpoints':[endpoint('ALINA updated: 48-month DFS, stage II–IIIA',74.5,46.3,'percent','0.36 (95% CI 0.23–0.56)','231 completely resected stage II–IIIA patients (AJCC/UICC 7th edition): 116 versus 115. DFS from randomisation; 8 December 2024 cutoff, ESMO 2025 conference analysis. Alectinib for up to 24 months versus four platinum-chemotherapy cycles; OS immature.',AU,'Platinum chemotherapy','DFS'),endpoint('ALINA updated: 48-month DFS, ITT stage IB–IIIA',75.5,47.0,'percent','0.35 (95% CI 0.23–0.54)','257 completely resected patients: 130 versus 127; stage IB required tumour ≥4 cm. DFS from randomisation; 8 December 2024 cutoff, ESMO 2025 conference analysis. This broader population must not be labelled stage II–IIIA. OS immature.',AU,'Platinum chemotherapy','DFS'),endpoint('ALEX final: median OS from randomisation',81.1,54.2,'months','0.78 (95% CI 0.56–1.08)','303 untreated advanced ALK-positive NSCLC patients: 152 versus 151. Data cutoff 28 April 2025. Final OS comparison did not establish a statistically significant difference; CI includes 1. Not an adjuvant or post-crizotinib result, and not a comparison with other modern ALK inhibitors.',AX,'Crizotinib','OS')],'additional_evidence':[{'indication_id':'00401a','trial':'Ou global phase II NP28673','result':'Independent-review ORR 50% (95% CI 41–59%) among 122 response-evaluable patients; 138 treated. Median PFS 8.9 months among all 138.','population':'Advanced ALK-positive NSCLC after crizotinib; 79% of response-evaluable patients had prior chemotherapy.','limitation':'Single-arm evidence without comparative OS inference; do not apply ALEX/ALINA survival estimates.','source_url':OU}],'limitations':limits,'harms':'Monitor liver injury, myotoxicity/CPK, anaemia including haemolysis, bradycardia, ILD, gastrointestinal symptoms and photosensitivity. Trial harm percentages depend on setting and exposure; no cross-trial safety ranking is made.','sources':[{'label':t,'url':u} for i,t,u in source_rows if i in ['alina','alina-update','alex-final','ou-phase2','smpc']],'checked':DATE}
journey={'stages':columns,'lanes':[{'label':x['label'],'kind':'treatment' if i==0 else 'monitoring','cells':x['cells'],'source_ids':['00401','smpc'],'note':'Relative timing; actual appointments confirmed locally.'} for i,x in enumerate(monitorrows)],'milestones':[{'title':'Confirm setting and baseline','when':'Before starting','why':'Adjuvant and advanced treatment have different endpoints.','clinical':'Validated ALK result, baseline bloods/CPK/BP/ECG, source eligibility; minimum 7 days after crizotinib for 00401a.','action':'Confirm indication, prescription, access and monitoring responsibilities.','source_ids':['00401','smpc']},{'title':'Early liver and muscle checks','when':'First month and first 3 months','why':'Important abnormalities can be asymptomatic.','clinical':'CPK every 2 weeks for first month; liver profile every 2 weeks for first 3 months.','action':'Keep blood tests and report new muscle/liver symptoms.','source_ids':['00401']},{'title':'Ongoing reviews','when':'Throughout treatment','why':'Benefit, tolerance and medicine interactions can change.','clinical':'FBC/renal every 4 weeks; liver every 4 weeks after month 3; BP/pulse and ECG as indicated.','action':'Confirm tests, symptom review, supply and disease assessment.','source_ids':['00401','smpc']},{'title':'Adjuvant completion or advanced change','when':'At planned endpoint or earlier clinical change','why':'A single duration does not fit all indications.','clinical':'Adjuvant maximum 24 months; earlier recurrence/toxicity may stop. Advanced until progression/unacceptable toxicity.','action':'Agree completion/follow-up or another treatment decision.','source_ids':['00401','smpc']}],'clinical_notes':['NCCP prior-to-cycle-2 ECG wording does not define a continuous oral cycle: confirm first repeat timing without inventing a 28-day cycle.',scope,schedule]}
