for id,label,detail,tier in [('liver','Liver injury','Raised liver tests and bilirubin can occur; liver injury may need interruption, dose reduction or stopping. Keep scheduled blood tests and report jaundice or dark urine.','serious'),('ild','Lung inflammation (ILD / pneumonitis)','New cough or breathlessness needs prompt assessment. Alectinib-related lung inflammation can require permanent discontinuation.','serious'),('muscles','Muscle injury / raised CPK','Unexplained muscle pain, tenderness or weakness needs review and CPK testing. Severe or recurrent elevations may require interruption and dose reduction.','serious'),('haemolysis','Anaemia including red-cell breakdown','Anaemia can include haemolysis. Report marked tiredness, pallor, breathlessness or dark urine; additional blood tests and treatment interruption may be required.','serious'),('bradycardia','Slow heart rate','Symptomatic or life-threatening bradycardia can occur. Dizziness or fainting needs urgent assessment and a review of other medicines.','serious'),('gi_perforation','Gastrointestinal perforation','Perforation has been reported in patients at increased risk. Severe abdominal pain needs urgent assessment; stopping may be considered.','serious'),('skin','Rash and sunlight sensitivity','Skin effects and photosensitivity can occur. Avoid prolonged sun exposure; use SPF 50 or higher sunscreen and lip balm during treatment and for at least 7 days after stopping.','important'),('daily_effects','Bowel symptoms, nausea and swelling','Constipation, nausea, diarrhoea and swelling can affect daily activities; report persistent symptoms and poor intake.','important'),('reproduction','Pregnancy, contraception and breastfeeding','Potential fetal harm. Highly effective contraception: women during treatment and ≥5 weeks afterwards; men with partners who could become pregnant during treatment and ≥3 months afterwards. Oral contraception may be less effective. Avoid breastfeeding and discuss fertility.','serious')]:consent['risks'].append({'id':id,'label':label,'detail':detail,'tier':tier})
